/****************************************************************************
 * touch_diag.c — 触摸屏诊断程序
 *
 * 直接通过 I2C 测试 FT6146 通信，不依赖 LVGL
 *
 * 用法：nsh> touch_diag
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <nuttx/i2c/i2c_master.h>

#define FT6146_ADDR     0x38
#define FT6146_REG_ID_H 0xA3
#define FT6146_REG_ID_L 0x9F
#define FT6146_REG_TD   0x02  /* Touch data register */

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_msg_s msgs[2];
  struct i2c_transfer_s xfer;

  msgs[0].addr   = FT6146_ADDR;
  msgs[0].flags  = 0;
  msgs[0].buffer = &reg;
  msgs[0].length = 1;

  msgs[1].addr   = FT6146_ADDR;
  msgs[1].flags  = I2C_M_READ;
  msgs[1].buffer = buf;
  msgs[1].length = len;

  xfer.msgv = msgs;
  xfer.msgc = 2;

  return ioctl(fd, I2CIOC_TRANSFER, (unsigned long)&xfer);
}

int main(int argc, char *argv[])
{
  uint8_t buf[8];
  int fd, ret;

  printf("=== Touch Diagnostic ===\n\n");

  /* 打开 I2C 总线 0 */

  fd = open("/dev/i2c0", O_RDWR);
  if (fd < 0)
    {
      printf("[FAIL] open /dev/i2c0 failed: %d\n", fd);
      return -1;
    }

  printf("[OK] /dev/i2c0 opened\n");

  /* 测试 1：扫描 I2C 地址 0x38 */

  printf("\n--- Test 1: I2C scan at 0x%02X ---\n", FT6146_ADDR);

  uint8_t test_reg = 0x00;
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = FT6146_ADDR;
  msg.flags  = 0;
  msg.buffer = &test_reg;
  msg.length = 1;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  ret = ioctl(fd, I2CIOC_TRANSFER, (unsigned long)&xfer);
  if (ret < 0)
    {
      printf("[FAIL] No ACK at 0x%02X (ret=%d)\n", FT6146_ADDR, ret);
      printf("  → Touch controller not responding on I2C\n");
      printf("  → Check: power supply, reset pin, I2C wiring\n");
    }
  else
    {
      printf("[OK] ACK at 0x%02X\n", FT6146_ADDR);
    }

  /* 测试 2：读取 FT6146 ID 寄存器 */

  printf("\n--- Test 2: Read FT6146 ID ---\n");

  ret = i2c_read_reg(fd, FT6146_REG_ID_H, buf, 1);
  if (ret < 0)
    {
      printf("[FAIL] Read ID_H (0xA3) failed: %d\n", ret);
    }
  else
    {
      printf("[OK] ID_H = 0x%02X\n", buf[0]);
    }

  ret = i2c_read_reg(fd, FT6146_REG_ID_L, buf, 1);
  if (ret < 0)
    {
      printf("[FAIL] Read ID_L (0x9F) failed: %d\n", ret);
    }
  else
    {
      printf("[OK] ID_L = 0x%02X\n", buf[0]);
    }

  /* 测试 3：读取触摸数据寄存器 */

  printf("\n--- Test 3: Read touch data ---\n");

  ret = i2c_read_reg(fd, FT6146_REG_TD, buf, 5);
  if (ret < 0)
    {
      printf("[FAIL] Read touch data failed: %d\n", ret);
    }
  else
    {
      printf("[OK] Touch data: %02X %02X %02X %02X %02X\n",
             buf[0], buf[1], buf[2], buf[3], buf[4]);

      int touch_num = buf[0] & 0x0F;
      if (touch_num > 0)
        {
          int x = ((buf[1] & 0x0F) << 8) | buf[2];
          int y = ((buf[3] & 0x0F) << 8) | buf[4];
          printf("  → Touch detected: (%d, %d)\n", x, y);
        }
      else
        {
          printf("  → No touch (touch_num=0)\n");
        }
    }

  /* 测试 4：多次扫描 */

  printf("\n--- Test 4: Continuous scan (5 times, 1s interval) ---\n");

  for (int i = 0; i < 5; i++)
    {
      ret = i2c_read_reg(fd, FT6146_REG_TD, buf, 5);
      if (ret < 0)
        {
          printf("[%d] I2C read failed\n", i);
        }
      else
        {
          int touch_num = buf[0] & 0x0F;
          if (touch_num > 0)
            {
              int x = ((buf[1] & 0x0F) << 8) | buf[2];
              int y = ((buf[3] & 0x0F) << 8) | buf[4];
              printf("[%d] Touch: (%d, %d)\n", i, x, y);
            }
          else
            {
              printf("[%d] No touch\n", i);
            }
        }

      sleep(1);
    }

  close(fd);
  printf("\n=== Diagnostic complete ===\n");
  return 0;
}
